import org.junit.jupiter.api.Test;

class FilterInValuesOptimizerTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void usesGuaranteedJoinInputToAnchorFilterInValues() throws Exception {
		IRI selected = VF.createIRI("urn:selected");
		IRI other = VF.createIRI("urn:other");
		MapBindingSet input = new MapBindingSet();
		input.addBinding("x", selected);

		ListMemberOperator condition = new ListMemberOperator();
		condition.addArgument(Var.of("x"));
		condition.addArgument(new ValueConstant(selected));
		condition.addArgument(new ValueConstant(other));
		QueryRoot original = new QueryRoot(new Join(values("x", selected), new Filter(new SingletonSet(), condition)));
		List<BindingSet> expected = evaluate(original.clone(), EmptyBindingSet.getInstance());
		assertThat(expected).singleElement().satisfies(row -> assertThat(row.getValue("x")).isEqualTo(selected));

		QueryRoot optimized = original.clone();
		new FilterInValuesOptimizer().optimize(optimized, null, input);

		assertThat(((Join) optimized.getArg()).getRightArg()).isInstanceOf(Join.class);
		assertThat(evaluate(optimized, EmptyBindingSet.getInstance())).containsExactlyElementsOf(expected);
	}

	private static BindingSetAssignment values(String name, IRI value) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, value);
		assignment.setBindingSets(List.of(row));
		return assignment;
	}

	private static List<BindingSet> evaluate(QueryRoot expression, BindingSet bindings) throws Exception {
		EvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<BindingSet> result = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, bindings)) {
			while (iteration.hasNext()) {
				result.add(iteration.next());
			}
		}
		return result;
	}
}
